  /** define reset %s */
  function p_reset(t: T, a_iframes: Value): void {
    replaceItem(G.l.Num_G_PastInputs, t.v.p, "");
    t.v.timer = "0";
    if (eq(item(G.l.P_Char, t.v.p), 99)) {
      p_break_(t, item(G.l.Num_MD_CS, 1), item(G.l.P_Char, t.v.p));
    } else {
      p_break_(t, item(G.l.Num_MD_CS, item(G.l.P_Char, t.v.p)), item(G.l.P_Char, t.v.p));
    }
    t.v.youonlygetone = "0";
    t.v.shorthop = "0";
    replaceItem(G.l.P_Death, t.v.p, "0");
    t.v.footsietimer = 30;
    t.switchCostume(("hitbox" + String(item(G.l.P_Char, t.v.p))));
    if (eq(t.v.p, 1)) {
      t.setXY(-150, 0);
    } else {
      t.setXY(150, 0);
    }
    t.show();
    p_p_update_Num_delta_Plus_set(t, "2", "", "0", "set");
    p_p_update_Num_delta_Plus_set(t, "1", "", "Idle", "set");
    replaceItem(G.l.P_ShieldStun, t.v.p, "0");
    replaceItem(G.l.P_StatusEffects, t.v.p, "");
    replaceItem(G.l.P_StatusEffects, (num(t.v.p) + 2), "");
    replaceItem(G.l.P_Velocity, (num((num(t.v.p) * 2)) - 1), "0");
    replaceItem(G.l.P_Velocity, (num(t.v.p) * 2), "0");
    p_p_update_Num_delta_Plus_set(t, "2", "2", "0", "set");
    p_p_update_Num_delta_Plus_set(t, "2", "4", "0", "set");
    replaceItem(G.l.P_Shield, t.v.p, 50);
    replaceItem(G.l.P_Stun, t.v.p, "0");
    p_p_update_Num_delta_Plus_set(t, "3", "", item(G.l.savedhp, t.v.p), "set");
    if (eq(G.v.Num_storybattle, 2)) {
      if (eq(t.v.p, 2)) {
        p_p_update_Num_delta_Plus_set(t, "3", "", (num(item(G.l.P_HP, t.v.p)) * num(G.v._2HPmod)), "set");
      }
    }
    if (listContains(t.l.mymod, 2)) {
      p_p_update_Num_delta_Plus_set(t, "3", "", 100, "set");
    }
    replaceItem(G.l.P_Invincibility, t.v.p, a_iframes);
    replaceItem(G.l.P_GrabList, t.v.p, "0");
    replaceItem(G.l.P_Stunlock, t.v.p, "0");
    if ((eq(t.v.p, 1) && (eq(G.v.Num_storybattle, 2) && bool(item(G.l.Num_T_Chal, 14))))) {
      replaceItem(G.l.ram, 35, item(G.l.savedhp, 1));
    }
    replaceItem(G.l.P_Percent, (num(t.v.p) + 2), "0");
    replaceItem(G.l.P_Percent, t.v.p, "0");
    if (eq(G.v.GlobalMode, 2)) {
      rt.startSound(t, "trip");
      replaceItem(G.l.P_HP, t.v.p, 300);
    }
    rt.broadcast(("respawn" + String(t.v.p)));
  }

