  /** define wiggle */
  function p_wiggle(t: T): void {
    t.v.ww = "1";
    while (!!rt.touching(t, "Stage")) {
      t.setXY(t.x, t.y + num(t.v.ww));
      if (rt.touching(t, "Stage")) {
        t.setXY(t.x, t.y + num((num(t.v.ww) * -2)));
        if (rt.touching(t, "Stage")) {
          t.setXY(t.x, t.y + num(t.v.ww));
          t.setXY(t.x + num(t.v.ww), t.y);
          if (rt.touching(t, "Stage")) {
            t.setXY(t.x + num((num(t.v.ww) * -2)), t.y);
            if (rt.touching(t, "Stage")) {
              t.setXY(t.x + num(t.v.ww), t.y);
            }
          }
        }
      }
      t.v.ww = num(t.v.ww) + 1;
    }
  }

